mapper.select:
SELECT n.notif_id AS notification_id, n.notif_type AS type, wn.property_id, wn.before_value, wn.after_value, n.is_read AS read, n.created_at AT TIME ZONE 'Asia/Seoul' AS created_at FROM notification n LEFT JOIN wishlist_notification wn ON wn.notif_id = n.notif_id WHERE n.user_id = #{userId}
AND n.notif_id < #{lastNotificationId}
ORDER BY n.notif_id DESC LIMIT #{limit}
